enum class NodeType
{
  UNDEFINED = 0,
  ACTION,
  CONDITION,
  CONTROL,
  DECORATOR,
  SUBTREE
};

enum class NodeStatus
{
  IDLE = 0,
  RUNNING = 1,
  SUCCESS = 2,
  FAILURE = 3,
  SKIPPED = 4,
};

enum class PortDirection
{
  INPUT,
  OUTPUT,
  INOUT
};

struct AnyTypeAllowed
{
};

struct Timestamp
{
  // Number being incremented every time a new value is written
  uint64_t seq = 0;
  // Last update time. Nanoseconds since epoch
  std::chrono::nanoseconds time = std::chrono::nanoseconds(0);
};

class TypeInfo
{
public:
  template <typename T>
  static TypeInfo Create()
  {
    return TypeInfo{ typeid(T), GetAnyFromStringFunctor<T>() };
  }

  TypeInfo() : type_info_(typeid(AnyTypeAllowed)), type_str_("AnyTypeAllowed")
  {}

  TypeInfo(std::type_index type_info, StringConverter conv)
    : type_info_(type_info), converter_(conv), type_str_(BT::demangle(type_info))
  {}

  [[nodiscard]] const std::type_index& type() const;

  [[nodiscard]] const std::string& typeName() const;

  [[nodiscard]] Any parseString(const char* str) const;

  [[nodiscard]] Any parseString(const std::string& str) const;

  template <typename T>
  [[nodiscard]] Any parseString(const T&) const
  {
    // avoid compilation errors
    return {};
  }

  [[nodiscard]] bool isStronglyTyped() const
  {
    return type_info_ != typeid(AnyTypeAllowed) && type_info_ != typeid(BT::Any);
  }

  [[nodiscard]] const StringConverter& converter() const
  {
    return converter_;
  }

private:
  std::type_index type_info_;
  StringConverter converter_;
  std::string type_str_;
};

class PortInfo : public TypeInfo
{
public:
  PortInfo(PortDirection direction = PortDirection::INOUT)
    : TypeInfo(), direction_(direction)
  {}

  PortInfo(PortDirection direction, std::type_index type_info, StringConverter conv)
    : TypeInfo(type_info, conv), direction_(direction)
  {}

  [[nodiscard]] PortDirection direction() const;

  void setDescription(StringView description);

  template <typename T>
  void setDefaultValue(const T& default_value)
  {
    default_value_ = Any(default_value);
    try
    {
      default_value_str_ = BT::toStr(default_value);
    }
    catch(LogicError&)
    {}
  }

  [[nodiscard]] const std::string& description() const;

  [[nodiscard]] const Any& defaultValue() const;

  [[nodiscard]] const std::string& defaultValueString() const;

private:
  PortDirection direction_;
  std::string description_;
  Any default_value_;
  std::string default_value_str_;
};

struct TreeNodeManifest
{
  NodeType type;
  std::string registration_ID;
  PortsList ports;
  KeyValueVector metadata;
};

enum class PreCond
{
  // order of the enums also tell us the execution order
  FAILURE_IF = 0,
  SUCCESS_IF,
  SKIP_IF,
  WHILE_TRUE,
  COUNT_
};

enum class PostCond
{
  // order of the enums also tell us the execution order
  ON_HALTED = 0,
  ON_FAILURE,
  ON_SUCCESS,
  ALWAYS,
  COUNT_
};

struct NodeConfig
{
  NodeConfig()
  {}

  // Pointer to the blackboard used by this node
  Blackboard::Ptr blackboard;
  // List of enums available for scripting
  std::shared_ptr<ScriptingEnumsRegistry> enums;
  // input ports
  PortsRemapping input_ports;
  // output ports
  PortsRemapping output_ports;

  // Any other attributes found in the xml that are not parsed as ports
  // or built-in identifier (e.g. anything with a leading '_')
  NonPortAttributes other_attributes;

  const TreeNodeManifest* manifest = nullptr;

  // Numeric unique identifier
  uint16_t uid = 0;
  // Unique human-readable name, that encapsulate the subtree
  // hierarchy, for instance, given 2 nested trees, it should be:
  //
  //   main_tree/nested_tree/my_action
  std::string path;

  std::map<PreCond, std::string> pre_conditions;
  std::map<PostCond, std::string> post_conditions;
};

// back compatibility
using NodeConfiguration = NodeConfig;

class TreeNode
{
public:
  typedef std::shared_ptr<TreeNode> Ptr;
  TreeNode(std::string name, NodeConfig config);
  TreeNode(const TreeNode& other) = delete;
  TreeNode& operator=(const TreeNode& other) = delete;
  TreeNode(TreeNode&& other) noexcept;
  TreeNode& operator=(TreeNode&& other) noexcept;
  virtual ~TreeNode();
  virtual BT::NodeStatus executeTick();
  void haltNode();
  [[nodiscard]] bool isHalted() const;
  [[nodiscard]] NodeStatus status() const;
  [[nodiscard]] const std::string& name() const;
  [[nodiscard]] BT::NodeStatus waitValidStatus();
  virtual NodeType type() const = 0;
  using StatusChangeSignal = Signal<TimePoint, const TreeNode&, NodeStatus, NodeStatus>;
  using StatusChangeSubscriber = StatusChangeSignal::Subscriber;
  using StatusChangeCallback = StatusChangeSignal::CallableFunction;
  using PreTickCallback = std::function<NodeStatus(TreeNode&)>;
  using PostTickCallback = std::function<NodeStatus(TreeNode&, NodeStatus)>;
  using TickMonitorCallback =
      std::function<void(TreeNode&, NodeStatus, std::chrono::microseconds)>;
  [[nodiscard]] StatusChangeSubscriber
  subscribeToStatusChange(StatusChangeCallback callback);
  void setPreTickFunction(PreTickCallback callback);
  void setPostTickFunction(PostTickCallback callback);
  void setTickMonitorCallback(TickMonitorCallback callback);
  [[nodiscard]] uint16_t UID() const;
  [[nodiscard]] const std::string& fullPath() const;
  [[nodiscard]] const std::string& registrationName() const;
  [[nodiscard]] const NodeConfig& config() const;
  template <typename T>
  Result getInput(const std::string& key, T& destination) const;
  template <typename T>
  [[nodiscard]] Expected<Timestamp> getInputStamped(const std::string& key,
                                                    T& destination) const;
  template <typename T>
  [[nodiscard]] Expected<T> getInput(const std::string& key) const
  { /* ... inline body present above ... */ }
  template <typename T>
  [[nodiscard]] Expected<StampedValue<T>> getInputStamped(const std::string& key) const
  { /* ... inline body present above ... */ }
  template <typename T>
  Result setOutput(const std::string& key, const T& value);
  [[nodiscard]] AnyPtrLocked getLockedPortContent(const std::string& key);
  [[nodiscard]] StringView getRawPortValue(const std::string& key) const;
  [[nodiscard]] static bool isBlackboardPointer(StringView str,
                                                StringView* stripped_pointer = nullptr);
  [[nodiscard]] static StringView stripBlackboardPointer(StringView str);
  [[nodiscard]] static Expected<StringView> getRemappedKey(StringView port_name,
                                                           StringView remapped_port);
  void emitWakeUpSignal();
  [[nodiscard]] bool requiresWakeUp() const;
  template <class DerivedT, typename... ExtraArgs>
  static std::unique_ptr<TreeNode> Instantiate(const std::string& name,
                                               const NodeConfig& config,
                                               ExtraArgs... args)
  { /* ... inline body present above ... */ }
protected:
  friend class BehaviorTreeFactory;
  friend class DecoratorNode;
  friend class ControlNode;
  friend class Tree;
  [[nodiscard]] NodeConfig& config();
  virtual BT::NodeStatus tick() = 0;
  void resetStatus();
  void setRegistrationID(StringView ID);
  void setWakeUpInstance(std::shared_ptr<WakeUpSignal> instance);
  void modifyPortsRemapping(const PortsRemapping& new_remapping);
  void setStatus(NodeStatus new_status);
  using PreScripts = std::array<ScriptFunction, size_t(PreCond::COUNT_)>;
  using PostScripts = std::array<ScriptFunction, size_t(PostCond::COUNT_)>;
  PreScripts& preConditionsScripts();
  PostScripts& postConditionsScripts();
  template <typename T>
  T parseString(const std::string& str) const;
private:
  struct PImpl;
  std::unique_ptr<PImpl> _p;
  Expected<NodeStatus> checkPreConditions();
  void checkPostConditions(NodeStatus status);
  virtual void halt() = 0;
};

namespace BT
{
class LeafNode : public TreeNode
{
protected:
public:
  LeafNode(const std::string& name, const NodeConfig& config) : TreeNode(name, config)
  {}

  virtual ~LeafNode() override = default;
};
}  // namespace BT

class ActionNodeBase : public LeafNode
{
public:
  ActionNodeBase(const std::string& name, const NodeConfig& config);
  ~ActionNodeBase() override = default;

  virtual NodeType type() const override final
  {
    return NodeType::ACTION;
  }
};

class SyncActionNode : public ActionNodeBase
{
public:
  SyncActionNode(const std::string& name, const NodeConfig& config);
  ~SyncActionNode() override = default;

  /// throws if the derived class return RUNNING.
  virtual NodeStatus executeTick() override;

  /// You don't need to override this
  virtual void halt() override final
  {
    resetStatus();
  }
};

class SimpleActionNode : public SyncActionNode
{
public:
  using TickFunctor = std::function<NodeStatus(TreeNode&)>;

  // You must provide the function to call when tick() is invoked
  SimpleActionNode(const std::string& name, TickFunctor tick_functor,
                   const NodeConfig& config);

  ~SimpleActionNode() override = default;

protected:
  virtual NodeStatus tick() override final;

  TickFunctor tick_functor_;
};

class ThreadedAction : public ActionNodeBase
{
public:
  ThreadedAction(const std::string& name, const NodeConfig& config)
    : ActionNodeBase(name, config)
  {}

  bool isHaltRequested() const
  {
    return halt_requested_.load();
  }

  // This method spawn a new thread. Do NOT remove the "final" keyword.
  virtual NodeStatus executeTick() override final;

  virtual void halt() override;

private:
  std::exception_ptr exptr_;
  std::atomic_bool halt_requested_ = false;
  std::future<void> thread_handle_;
  std::mutex mutex_;
};

#ifdef USE_BTCPP3_OLD_NAMES
using AsyncActionNode = ThreadedAction;
#endif

class StatefulActionNode : public ActionNodeBase
{
public:
  StatefulActionNode(const std::string& name, const NodeConfig& config)
    : ActionNodeBase(name, config)
  {}

  /// Method called once, when transitioning from the state IDLE.
  /// If it returns RUNNING, this becomes an asynchronous node.
  virtual NodeStatus onStart() = 0;

  /// method invoked when the action is already in the RUNNING state.
  virtual NodeStatus onRunning() = 0;

  /// when the method halt() is called and the action is RUNNING, this method is invoked.
  /// This is a convenient place todo a cleanup, if needed.
  virtual void onHalted() = 0;

  bool isHaltRequested() const;

protected:
  // do not override this method
  NodeStatus tick() override final;
  // do not override this method
  void halt() override final;

private:
  std::atomic_bool halt_requested_ = false;
};

class CoroActionNode : public ActionNodeBase
{
public:
  CoroActionNode(const std::string& name, const NodeConfig& config);
  virtual ~CoroActionNode() override;

  /// Use this method to return RUNNING and temporary "pause" the Action.
  void setStatusRunningAndYield();

  // This method triggers the TickEngine. Do NOT remove the "final" keyword.
  virtual NodeStatus executeTick() override final;

  // Used internally, but it needs to be public
  void tickImpl();

  /** You may want to override this method. But still, remember to call this
    * implementation too.
    *
    * Example:
    *
    *     void MyAction::halt()
    *     {
    *         // do your stuff here
    *         CoroActionNode::halt();
    *     }
    */
  void halt() override;

protected:
  struct Pimpl;  // The Pimpl idiom
  std::unique_ptr<Pimpl> _p;

  void destroyCoroutine();
};

namespace BT
{
class ConditionNode : public LeafNode
{
public:
  ConditionNode(const std::string& name, const NodeConfig& config);

  virtual ~ConditionNode() override = default;

  //Do nothing
  virtual void halt() override final
  {
    resetStatus();
  }

  virtual NodeType type() const override final
  {
    return NodeType::CONDITION;
  }
};
}  // namespace BT

namespace BT
{
class SimpleConditionNode : public ConditionNode
{
public:
  using TickFunctor = std::function<NodeStatus(TreeNode&)>;

  // You must provide the function to call when tick() is invoked
  SimpleConditionNode(const std::string& name, TickFunctor tick_functor,
                      const NodeConfig& config);

  ~SimpleConditionNode() override = default;

protected:
  virtual NodeStatus tick() override;

  TickFunctor tick_functor_;
};
}  // namespace BT

namespace BT
{
class DecoratorNode : public TreeNode
{
protected:
  TreeNode* child_node_;

public:
  DecoratorNode(const std::string& name, const NodeConfig& config);

  virtual ~DecoratorNode() override = default;

  void setChild(TreeNode* child);

  const TreeNode* child() const;

  TreeNode* child();

  /// The method used to interrupt the execution of this node
  virtual void halt() override;

  /// Same as resetChild()
  void haltChild();

  virtual NodeType type() const override
  {
    return NodeType::DECORATOR;
  }

  NodeStatus executeTick() override;

  /// Set the status of the child to IDLE.
  /// also send a halt() signal to a RUNNING child
  void resetChild();
};
}

namespace BT
{
class SimpleDecoratorNode : public DecoratorNode
{
public:
  using TickFunctor = std::function<NodeStatus(NodeStatus, TreeNode&)>;

  // You must provide the function to call when tick() is invoked
  SimpleDecoratorNode(const std::string& name, TickFunctor tick_functor,
                      const NodeConfig& config);

  ~SimpleDecoratorNode() override = default;

protected:
  virtual NodeStatus tick() override;

  TickFunctor tick_functor_;
};
}

namespace BT
{
class ControlNode : public TreeNode
{
protected:
  std::vector<TreeNode*> children_nodes_;

public:
  ControlNode(const std::string& name, const NodeConfig& config);

  virtual ~ControlNode() override = default;

  /// The method used to add nodes to the children vector
  void addChild(TreeNode* child);

  size_t childrenCount() const;

  const std::vector<TreeNode*>& children() const;

  const TreeNode* child(size_t index) const
  {
    return children().at(index);
  }

  virtual void halt() override;

  /// same as resetChildren()
  void haltChildren();

  [[deprecated("deprecated: please use explicitly haltChildren() or haltChild(i)")]] void
  haltChildren(size_t first);

  void haltChild(size_t i);

  virtual NodeType type() const override final
  {
    return NodeType::CONTROL;
  }

  /// Set the status of all children to IDLE.
  /// also send a halt() signal to all RUNNING children
  void resetChildren();
};
}  // namespace BT

class Blackboard
{
public:
  using Ptr = std::shared_ptr<Blackboard>;

protected:
  // This is intentionally protected. Use Blackboard::create instead
  Blackboard(Blackboard::Ptr parent) : parent_bb_(parent)
  {}

public:
  struct Entry
  {
    Any value;
    TypeInfo info;
    StringConverter string_converter;
    mutable std::mutex entry_mutex;

    uint64_t sequence_id = 0;
    // timestamp since epoch
    std::chrono::nanoseconds stamp = std::chrono::nanoseconds{ 0 };

    Entry(const TypeInfo& _info) : info(_info)
    {}

    Entry& operator=(const Entry& other);
  };

  /** Use this static method to create an instance of the BlackBoard
    *   to share among all your NodeTrees.
    */
  static Blackboard::Ptr create(Blackboard::Ptr parent = {})
  {
    return std::shared_ptr<Blackboard>(new Blackboard(parent));
  }

  virtual ~Blackboard() = default;

  void enableAutoRemapping(bool remapping);

  [[nodiscard]] const std::shared_ptr<Entry> getEntry(const std::string& key) const;

  [[nodiscard]] std::shared_ptr<Blackboard::Entry> getEntry(const std::string& key);

  [[nodiscard]] AnyPtrLocked getAnyLocked(const std::string& key);

  [[nodiscard]] AnyPtrLocked getAnyLocked(const std::string& key) const;

  [[deprecated("Use getAnyLocked instead")]] const Any*
  getAny(const std::string& key) const;

  [[deprecated("Use getAnyLocked instead")]] Any* getAny(const std::string& key);

  template <typename T>
  [[nodiscard]] bool get(const std::string& key, T& value) const;

  template <typename T>
  [[nodiscard]] Expected<Timestamp> getStamped(const std::string& key, T& value) const;

  template <typename T>
  [[nodiscard]] T get(const std::string& key) const;

  template <typename T>
  [[nodiscard]] Expected<StampedValue<T>> getStamped(const std::string& key) const;

  template <typename T>
  void set(const std::string& key, const T& value);

  void unset(const std::string& key);

  [[nodiscard]] const TypeInfo* entryInfo(const std::string& key);

  void addSubtreeRemapping(StringView internal, StringView external);

  void debugMessage() const;

  [[nodiscard]] std::vector<StringView> getKeys() const;

  [[deprecated("This command is unsafe. Consider using Backup/Restore instead")]] void
  clear();

  [[deprecated("Use getAnyLocked to access safely an Entry")]] std::recursive_mutex&
  entryMutex() const;

  void createEntry(const std::string& key, const TypeInfo& info);

  void cloneInto(Blackboard& dst) const;

  Blackboard::Ptr parent();

  Blackboard* rootBlackboard();

  const Blackboard* rootBlackboard() const;

private:
  mutable std::mutex storage_mutex_;
  mutable std::recursive_mutex entry_mutex_;
  std::unordered_map<std::string, std::shared_ptr<Entry>> storage_;
  std::weak_ptr<Blackboard> parent_bb_;
  std::unordered_map<std::string, std::string> internal_to_external_;

  std::shared_ptr<Entry> createEntryImpl(const std::string& key, const TypeInfo& info);

  bool autoremapping_ = false;
};

struct Entry
  {
    Any value;
    TypeInfo info;
    StringConverter string_converter;
    mutable std::mutex entry_mutex;

    uint64_t sequence_id = 0;
    // timestamp since epoch
    std::chrono::nanoseconds stamp = std::chrono::nanoseconds{ 0 };

    Entry(const TypeInfo& _info) : info(_info)
    {}

    Entry& operator=(const Entry& other);
  };

namespace BT
{
class BehaviorTreeException : public std::exception
{
public:
  BehaviorTreeException(std::string_view message)
    : message_(static_cast<std::string>(message))
  {}

  template <typename... SV>
  BehaviorTreeException(const SV&... args) : message_(StrCat(args...))
  {}

  const char* what() const noexcept
  {
    return message_.c_str();
  }

private:
  std::string message_;
};
}  // namespace BT

namespace BT
{
// This errors are usually related to problems which "probably" require code refactoring
// to be fixed.
class LogicError : public BehaviorTreeException
{
public:
  LogicError(std::string_view message) : BehaviorTreeException(message)
  {}

  template <typename... SV>
  LogicError(const SV&... args) : BehaviorTreeException(args...)
  {}
};
}  // namespace BT

namespace BT
{
// This errors are usually related to problems that are relted to data or conditions
// that happen only at run-time
class RuntimeError : public BehaviorTreeException
{
public:
  RuntimeError(std::string_view message) : BehaviorTreeException(message)
  {}

  template <typename... SV>
  RuntimeError(const SV&... args) : BehaviorTreeException(args...)
  {}
};

}  // namespace BT

namespace BT
{
/**
 * @brief The BehaviorTreeParser is a class used to read the model
 * of a BehaviorTree from file or text and instantiate the
 * corresponding tree using the BehaviorTreeFactory.
 */
class Parser
{
public:
  Parser() = default;

  virtual ~Parser() = default;

  Parser(const Parser& other) = delete;
  Parser& operator=(const Parser& other) = delete;

  Parser(Parser&& other) = default;
  Parser& operator=(Parser&& other) = default;

  virtual void loadFromFile(const std::filesystem::path& filename,
                            bool add_includes = true) = 0;

  virtual void loadFromText(const std::string& xml_text, bool add_includes = true) = 0;

  virtual std::vector<std::string> registeredBehaviorTrees() const = 0;

  virtual Tree instantiateTree(const Blackboard::Ptr& root_blackboard,
                               std::string tree_name = {}) = 0;

  virtual void clearInternalState(){};
};

}  // namespace BT

class Tree
{
public:
  // a tree can contain multiple subtree.
  struct Subtree
  {
    using Ptr = std::shared_ptr<Subtree>;
    std::vector<TreeNode::Ptr> nodes;
    Blackboard::Ptr blackboard;
    std::string instance_name;
    std::string tree_ID;
  };

  std::vector<Subtree::Ptr> subtrees;
  std::unordered_map<std::string, TreeNodeManifest> manifests;

  Tree();

  Tree(const Tree&) = delete;
  Tree& operator=(const Tree&) = delete;

  Tree(Tree&& other) = default;
  Tree& operator=(Tree&& other) = default;

  void initialize();

  void haltTree();

  [[nodiscard]] TreeNode* rootNode() const;

  bool sleep(std::chrono::system_clock::duration timeout);

  void emitWakeUpSignal();

  ~Tree();

  NodeStatus tickExactlyOnce();

  NodeStatus tickOnce();

  NodeStatus
  tickWhileRunning(std::chrono::milliseconds sleep_time = std::chrono::milliseconds(10));

  [[nodiscard]] Blackboard::Ptr rootBlackboard();

  void applyVisitor(const std::function<void(const TreeNode*)>& visitor) const;

  void applyVisitor(const std::function<void(TreeNode*)>& visitor);

  [[nodiscard]] uint16_t getUID();

  template <typename NodeType = BT::TreeNode>
  [[nodiscard]] std::vector<const TreeNode*>
  getNodesByPath(StringView wildcard_filter) const
  {
    std::vector<const TreeNode*> nodes;
    for(auto const& subtree : subtrees)
    {
      for(auto const& node : subtree->nodes)
      {
        if(auto node_recast = dynamic_cast<const NodeType*>(node.get()))
        {
          if(WildcardMatch(node->fullPath(), wildcard_filter))
          {
            nodes.push_back(node.get());
          }
        }
      }
    }
    return nodes;
  }

private:
  std::shared_ptr<WakeUpSignal> wake_up_;

  enum TickOption
  {
    EXACTLY_ONCE,
    ONCE_UNLESS_WOKEN_UP,
    WHILE_RUNNING
  };

  NodeStatus tickRoot(TickOption opt, std::chrono::milliseconds sleep_time);

  uint16_t uid_counter_ = 0;
};

struct Subtree
  {
    using Ptr = std::shared_ptr<Subtree>;
    std::vector<TreeNode::Ptr> nodes;
    Blackboard::Ptr blackboard;
    std::string instance_name;
    std::string tree_ID;
  };

class BehaviorTreeFactory
{
public:
  BehaviorTreeFactory();
  ~BehaviorTreeFactory();

  BehaviorTreeFactory(const BehaviorTreeFactory& other) = delete;
  BehaviorTreeFactory& operator=(const BehaviorTreeFactory& other) = delete;

  BehaviorTreeFactory(BehaviorTreeFactory&& other) noexcept = default;
  BehaviorTreeFactory& operator=(BehaviorTreeFactory&& other) noexcept = default;

  bool unregisterBuilder(const std::string& ID);

  void registerBuilder(const TreeNodeManifest& manifest, const NodeBuilder& builder);

  template <typename T>
  void registerBuilder(const std::string& ID, const NodeBuilder& builder)
  {
    auto manifest = CreateManifest<T>(ID);
    registerBuilder(manifest, builder);
  }

  void registerSimpleAction(const std::string& ID,
                            const SimpleActionNode::TickFunctor& tick_functor,
                            PortsList ports = {});
  void registerSimpleCondition(const std::string& ID,
                               const SimpleConditionNode::TickFunctor& tick_functor,
                               PortsList ports = {});
  void registerSimpleDecorator(const std::string& ID,
                               const SimpleDecoratorNode::TickFunctor& tick_functor,
                               PortsList ports = {});

  void registerFromPlugin(const std::string& file_path);

  [[deprecated("Removed support for ROS1")]] void registerFromROSPlugins();

  void registerBehaviorTreeFromFile(const std::filesystem::path& filename);

  void registerBehaviorTreeFromText(const std::string& xml_text);

  [[nodiscard]] std::vector<std::string> registeredBehaviorTrees() const;

  void clearRegisteredBehaviorTrees();

  [[nodiscard]] std::unique_ptr<TreeNode> instantiateTreeNode(
      const std::string& name, const std::string& ID, const NodeConfig& config) const;

  template <typename T, typename... ExtraArgs>
  void registerNodeType(const std::string& ID, const PortsList& ports, ExtraArgs... args)
  {
    static_assert(std::is_base_of<ActionNodeBase, T>::value ||
                      std::is_base_of<ControlNode, T>::value ||
                      std::is_base_of<DecoratorNode, T>::value ||
                      std::is_base_of<ConditionNode, T>::value,
                  "[registerNode]: accepts only classed derived from either "
                  "ActionNodeBase, "
                  "DecoratorNode, ControlNode or ConditionNode");

    constexpr bool default_constructable =
        std::is_constructible<T, const std::string&>::value;
    constexpr bool param_constructable =
        std::is_constructible<T, const std::string&, const NodeConfig&,
                              ExtraArgs...>::value;

    static_assert(!std::is_abstract<T>::value,
                  "[registerNode]: Some methods are pure virtual. "
                  "Did you override the methods tick() and halt()?");

    static_assert(default_constructable || param_constructable,
       "[registerNode]: the registered class must have at least one of these two constructors:\n"
       "  (const std::string&, const NodeConfig&) or (const std::string&)\n"
       "Check also if the constructor is public!)");

    registerBuilder(CreateManifest<T>(ID, ports), CreateBuilder<T>(args...));
  }

  template <typename T, typename... ExtraArgs>
  void registerNodeType(const std::string& ID, ExtraArgs... args)
  {
    if constexpr(std::is_abstract_v<T>)
    {
      static_assert(!std::is_abstract_v<T>, "The Node type can't be abstract. "
                                            "Did you forget to implement an abstract "
                                            "method in the derived class?");
    }
    else
    {
      constexpr bool param_constructable =
          std::is_constructible<T, const std::string&, const NodeConfig&,
                                ExtraArgs...>::value;
      constexpr bool has_static_ports_list = has_static_method_providedPorts<T>::value;

      static_assert(!(param_constructable && !has_static_ports_list),
                    "[registerNode]: you MUST implement the static method:\n"
                    "  PortsList providedPorts();\n");

      static_assert(!(has_static_ports_list && !param_constructable),
                    "[registerNode]: since you have a static method providedPorts(),\n"
                    "you MUST add a constructor with signature:\n"
                    "(const std::string&, const NodeConfig&)\n");
    }
    registerNodeType<T>(ID, getProvidedPorts<T>(), args...);
  }

  [[nodiscard]] const std::unordered_map<std::string, NodeBuilder>& builders() const;

  [[nodiscard]] const std::unordered_map<std::string, TreeNodeManifest>&
  manifests() const;

  [[nodiscard]] const std::set<std::string>& builtinNodes() const;

  [[nodiscard]] Tree createTreeFromText(
      const std::string& text, Blackboard::Ptr blackboard = Blackboard::create());

  [[nodiscard]] Tree
  createTreeFromFile(const std::filesystem::path& file_path,
                     Blackboard::Ptr blackboard = Blackboard::create());

  [[nodiscard]] Tree createTree(const std::string& tree_name,
                                Blackboard::Ptr blackboard = Blackboard::create());

  void addMetadataToManifest(const std::string& node_id, const KeyValueVector& metadata);

  void registerScriptingEnum(StringView name, int value);

  template <typename EnumType>
  void registerScriptingEnums()
  {
    constexpr auto entries = magic_enum::enum_entries<EnumType>();
    for(const auto& it : entries)
    {
      registerScriptingEnum(it.second, static_cast<int>(it.first));
    }
  }

  void clearSubstitutionRules();

  using SubstitutionRule =
      std::variant<std::string, TestNodeConfig, std::shared_ptr<TestNodeConfig>>;

  void addSubstitutionRule(StringView filter, SubstitutionRule rule);

  void loadSubstitutionRuleFromJSON(const std::string& json_text);

  [[nodiscard]] const std::unordered_map<std::string, SubstitutionRule>&
  substitutionRules() const;

private:
  struct PImpl;
  std::unique_ptr<PImpl> _p;
};

