//------------ implementation ----------------------------

inline NodeStatus ForceSuccessNode::tick()
{
  setStatus(NodeStatus::RUNNING);

  const NodeStatus child_status = child_node_->executeTick();

  if(isStatusCompleted(child_status))
  {
    resetChild();
    return NodeStatus::SUCCESS;
  }

  // RUNNING or skipping
  return child_status;
}

